using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyStarRequirementCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/PurifyStarRequirementCustomDescription", order = 0)]
public class CometConvergenceCustomDescription : StarRequirementCustomDescription
{
	protected override string GetActionLocalizedDescription(string amountModified, BattleAction battleAction)
	{
		CometConvergenceAction cometConvergenceAction = battleAction as CometConvergenceAction;
		return cometConvergenceAction.CosmicDustAction.GetActionDescription(cometConvergenceAction.CosmicDustAmount) + "\n" + Smart.Format(base.localizationManager.GetLocalizedForEach(), cometConvergenceAction.PurifyCorruptAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)).RemoveLastIfDotOrCommaAndIfNotJapaneseNorKoreanNorTraditionalChinese(), GetRawLocalizedDescription(battleAction));
	}
}
